def end_staff_sign_ins(apps, schema_editor):
    """
    2FA becomes required: staff signed in before it must sign in again (and set it up), so
    nobody keeps working without it. TV Display and Registration Desk sign-ins stay, as
    those accounts don't use 2FA (an office TV keeps showing).
    """
    OutstandingToken = apps.get_model('token_blacklist', 'OutstandingToken')
    BlacklistedToken = apps.get_model('token_blacklist', 'BlacklistedToken')
    DolePersonnel = apps.get_model('ctms', 'DolePersonnel')
    from django.utils import timezone
    shared = DolePersonnel.objects.filter(role__in=('DISPLAY', 'REGISTRAR'), user__isnull=False).values_list('user_id', flat=True)
    live = (OutstandingToken.objects.filter(expires_at__gt=timezone.now(), blacklistedtoken__isnull=True)
            .exclude(user_id__in=list(shared)))
    BlacklistedToken.objects.bulk_create([BlacklistedToken(token=t) for t in live], ignore_conflicts=True)


